//! Replays `fixtures/dynbsp_tracker.txt` against `FMovingBrushTracker`.
//!
//! The fixture is generated by `Build/dynbsp_fixture_harness/gen_dynbsp_fixtures.sh`: the original
//! C++ `UnDynBsp.cpp` (pre-port body) driven through three scripted cases. Each operation is
//! followed by a dump of the model state; this test re-renders the Rust state in the same line
//! format and requires identical lines.
//!
//! `COORDS` lines are inputs, not outputs: they hold the oracle's `ABrush::BuildCoords` result for
//! the pose at that point and are returned from the host's `build_coords`. They are excluded from
//! the comparison. `OP POSE` lines set actor location/rotation before the operation they precede.

use std::ffi::c_void;
use std::fmt::Debug;
use std::ptr::{self, NonNull};
use std::str::FromStr;

use hp2_abi::engine::generated::{FPoly, FRotator};
use hp2_abi::render_scene::{FBspNode, FBspSurf, FVert};
use hp2_abi::{FCoords, FPlane, FVector};
use hp2_engine::dynbsp::{DynBsp, DynBspHost, LogKind, Obj, Pool};

const FIXTURE: &str = include_str!("fixtures/dynbsp_tracker.txt");
const MAX_VERTICES: usize = 16;

/// Opaque actor/model handle: index + 1, so null stays the "none" value.
fn obj(i: usize) -> Obj {
    (i + 1) as *mut c_void
}

fn idx(o: Obj) -> usize {
    o as usize - 1
}

/// Actor index as the oracle's `actorIndex` prints it: -1 for null.
fn actor_ptr(i: i32) -> Obj {
    match i {
        -1 => ptr::null_mut(),
        k if k >= 0 => obj(k as usize),
        _ => panic!("unexpected actor index {i}"),
    }
}

fn actor_index(p: Obj) -> i32 {
    if p.is_null() { -1 } else { idx(p) as i32 }
}

fn texture_ptr(on: bool) -> *mut c_void {
    if on {
        NonNull::<c_void>::dangling().as_ptr()
    } else {
        ptr::null_mut()
    }
}

#[derive(Clone)]
struct Actor {
    mover: bool,
    location: FVector,
    rotation: FRotator,
    pre_pivot: FVector,
    saved_pos: FVector,
    saved_rot: FRotator,
    assimilated: bool,
    special_lit: bool,
    /// Model index of the actor's brush (movers only).
    brush: Option<usize>,
}

struct Model {
    link: i32,
    polys: Vec<FPoly>,
}

/// Host state: the level's model arrays, actors, and mover models.
#[derive(Default)]
struct World {
    surfs: Vec<FBspSurf>,
    vectors: Vec<FVector>,
    points: Vec<FVector>,
    nodes: Vec<FBspNode>,
    verts: Vec<FVert>,
    actors: Vec<Actor>,
    models: Vec<Model>,
    /// Oracle `BuildCoords` results per actor for the operation being replayed.
    coords: Vec<Option<(FCoords, FCoords, f32)>>,
}

impl World {
    /// Actor index of the `k`-th mover.
    fn mover_index(&self, k: usize) -> usize {
        self.actors
            .iter()
            .enumerate()
            .filter(|(_, a)| a.mover)
            .nth(k)
            .map(|(i, _)| i)
            .expect("mover ordinal out of range")
    }

    fn mover_obj(&self, k: usize) -> Obj {
        obj(self.mover_index(k))
    }
}

fn zero_vec() -> FVector {
    FVector {
        x: 0.0,
        y: 0.0,
        z: 0.0,
    }
}

fn zero_rot() -> FRotator {
    FRotator {
        pitch: 0,
        yaw: 0,
        roll: 0,
    }
}

impl DynBspHost for World {
    fn num(&self, pool: Pool) -> i32 {
        let n = match pool {
            Pool::Surfs => self.surfs.len(),
            Pool::Vectors => self.vectors.len(),
            Pool::Points => self.points.len(),
            Pool::Nodes => self.nodes.len(),
            Pool::Verts => self.verts.len(),
        };
        n as i32
    }

    fn set_num(&mut self, pool: Pool, n: i32) {
        let n = usize::try_from(n).expect("negative array size");
        // SAFETY: FBspSurf and FBspNode are plain data (ints, floats, raw pointers); all-zero is valid.
        match pool {
            Pool::Surfs => self.surfs.resize_with(n, || unsafe { std::mem::zeroed() }),
            Pool::Vectors => self.vectors.resize_with(n, zero_vec),
            Pool::Points => self.points.resize_with(n, zero_vec),
            Pool::Nodes => self.nodes.resize_with(n, || unsafe { std::mem::zeroed() }),
            Pool::Verts => self.verts.resize_with(n, || FVert {
                p_vertex: 0,
                i_side: 0,
            }),
        }
    }

    fn shrink(&mut self, _pool: Pool) {
        // Capacity is not part of the observable state.
    }

    fn remove(&mut self, pool: Pool, index: i32, count: i32) {
        let lo = usize::try_from(index).expect("negative index");
        let hi = usize::try_from(index + count).expect("negative count");
        match pool {
            Pool::Surfs => drop(self.surfs.drain(lo..hi)),
            Pool::Vectors => drop(self.vectors.drain(lo..hi)),
            Pool::Points => drop(self.points.drain(lo..hi)),
            Pool::Nodes => drop(self.nodes.drain(lo..hi)),
            Pool::Verts => drop(self.verts.drain(lo..hi)),
        }
    }

    fn surfs_mut(&mut self) -> &mut [FBspSurf] {
        &mut self.surfs
    }

    fn vectors_mut(&mut self) -> &mut [FVector] {
        &mut self.vectors
    }

    fn points_mut(&mut self) -> &mut [FVector] {
        &mut self.points
    }

    fn verts_mut(&mut self) -> &mut [FVert] {
        &mut self.verts
    }

    fn nodes_mut(&mut self) -> &mut [FBspNode] {
        &mut self.nodes
    }

    fn level_actor_count(&self) -> i32 {
        self.actors.len() as i32
    }

    fn level_actor(&self, i: i32) -> Obj {
        obj(usize::try_from(i).expect("negative actor index"))
    }

    fn level_full_name(&self) -> String {
        // Only used for log text, which is not part of the fixture.
        "harness".to_string()
    }

    fn is_moving_brush(&self, actor: Obj) -> bool {
        self.actors[idx(actor)].mover
    }

    fn is_mover(&self, actor: Obj) -> bool {
        self.actors[idx(actor)].mover
    }

    fn actor_name(&self, _actor: Obj) -> String {
        "actor".to_string()
    }

    fn location(&self, actor: Obj) -> FVector {
        self.actors[idx(actor)].location
    }

    fn rotation(&self, actor: Obj) -> FRotator {
        self.actors[idx(actor)].rotation
    }

    fn pre_pivot(&self, actor: Obj) -> FVector {
        self.actors[idx(actor)].pre_pivot
    }

    fn saved_pos(&self, actor: Obj) -> FVector {
        self.actors[idx(actor)].saved_pos
    }

    fn set_saved_pos(&mut self, actor: Obj, v: FVector) {
        self.actors[idx(actor)].saved_pos = v;
    }

    fn saved_rot(&self, actor: Obj) -> FRotator {
        self.actors[idx(actor)].saved_rot
    }

    fn set_saved_rot(&mut self, actor: Obj, r: FRotator) {
        self.actors[idx(actor)].saved_rot = r;
    }

    fn assimilated(&self, actor: Obj) -> bool {
        self.actors[idx(actor)].assimilated
    }

    fn set_assimilated(&mut self, actor: Obj, v: bool) {
        self.actors[idx(actor)].assimilated = v;
    }

    fn special_lit(&self, actor: Obj) -> bool {
        self.actors[idx(actor)].special_lit
    }

    fn brush(&self, actor: Obj) -> Obj {
        match self.actors[idx(actor)].brush {
            Some(k) => obj(k),
            None => ptr::null_mut(),
        }
    }

    fn build_coords(&mut self, actor: Obj) -> (FCoords, FCoords, f32) {
        self.coords[idx(actor)].expect("no oracle COORDS for actor")
    }

    fn brush_mover_link(&self, brush: Obj) -> i32 {
        self.models[idx(brush)].link
    }

    fn set_brush_mover_link(&mut self, brush: Obj, v: i32) {
        self.models[idx(brush)].link = v;
    }

    fn brush_polys(&mut self, brush: Obj) -> &mut [FPoly] {
        &mut self.models[idx(brush)].polys
    }

    fn debug(&mut self, _kind: LogKind, _msg: &str) {
        // Log text is not part of the fixture.
    }
}

// ---------------------------------------------------------------------------
// Rendering: the oracle's dump format (Build/dynbsp_fixture_harness/dynbsp_harness.cpp).
// ---------------------------------------------------------------------------

fn hx(f: f32) -> String {
    format!("{:08x}", f.to_bits())
}

fn hv(v: FVector) -> String {
    format!(" {} {} {}", hx(v.x), hx(v.y), hx(v.z))
}

fn hp(p: FPlane) -> String {
    format!(" {} {} {} {}", hx(p.x), hx(p.y), hx(p.z), hx(p.w))
}

fn hr(r: FRotator) -> String {
    format!(" {} {} {}", r.pitch, r.yaw, r.roll)
}

/// Renders the state as the oracle does. `sdyn` is `Some` when a tracker is alive.
fn render(w: &World, sdyn: Option<&dyn Fn(i32) -> bool>) -> Vec<String> {
    let mut out = Vec::new();
    for (i, s) in w.surfs.iter().enumerate() {
        out.push(format!(
            "SURF {i} {} {} {} {} {} {} {} {} {} {} {} {} {}",
            u8::from(!s.texture.is_null()),
            s.poly_flags,
            s.p_base,
            s.v_normal,
            s.v_texture_u,
            s.v_texture_v,
            s.i_light_map,
            s.i_brush_poly,
            i32::from(s.pan_u),
            i32::from(s.pan_v),
            actor_index(s.actor),
            s.decals.array_num,
            s.nodes.array_num,
        ));
        if let Some(f) = sdyn {
            out.push(format!("SDYN {i} {}", u8::from(f(i as i32))));
        }
    }
    for (i, v) in w.vectors.iter().enumerate() {
        out.push(format!("VEC {i}{}", hv(*v)));
    }
    for (i, v) in w.points.iter().enumerate() {
        out.push(format!("PT {i}{}", hv(*v)));
    }
    for (i, n) in w.nodes.iter().enumerate() {
        out.push(format!(
            "NODE {i}{} {} {} {} {} {} {} {} {} {} {} {} {} {} {}",
            hp(n.plane),
            n.zone_mask,
            n.i_vert_pool,
            n.i_surf,
            n.i_back,
            n.i_front,
            n.i_plane,
            n.i_collision_bound,
            n.i_render_bound,
            n.i_zone[0],
            n.i_zone[1],
            n.num_vertices,
            n.node_flags,
            n.i_leaf[0],
            n.i_leaf[1],
        ));
    }
    for (i, v) in w.verts.iter().enumerate() {
        out.push(format!("VERT {i} {} {}", v.p_vertex, v.i_side));
    }
    for (i, a) in w.actors.iter().enumerate() {
        if !a.mover {
            out.push(format!("ACTOR {i} plain"));
            continue;
        }
        out.push(format!(
            "ACTOR {i} mover{}{}{}{}{} {} {}",
            hv(a.location),
            hr(a.rotation),
            hv(a.pre_pivot),
            hv(a.saved_pos),
            hr(a.saved_rot),
            u8::from(a.assimilated),
            u8::from(a.special_lit),
        ));
        out.push(format!("BRUSH {i} {}", a.brush.map_or(-1, |k| k as i32)));
    }
    for (i, m) in w.models.iter().enumerate() {
        out.push(format!("MODEL {i} link {} polys {}", m.link, m.polys.len()));
        for (j, p) in m.polys.iter().enumerate() {
            let mut s = format!("BPOLY {i} {j}");
            for v in [p.base, p.normal, p.texture_u, p.texture_v] {
                s += &hv(v);
            }
            for v in p.vertex.iter() {
                s += &hv(*v);
            }
            s += &format!(
                " {} {} {} {} {} {} {} {} {}",
                p.poly_flags,
                actor_index(p.actor),
                p.num_vertices,
                p.i_link,
                p.i_brush_poly,
                i32::from(p.pan_u),
                i32::from(p.pan_v),
                p.save_poly_index,
                p.b_face_drag_sel,
            );
            out.push(s);
        }
    }
    let live = if sdyn.is_some() { live_nodes(w) } else { 0 };
    out.push(format!("LIVE {live}"));
    out
}

/// Counts sporadic nodes reachable from mover `MoverLink` chains via `iRenderBound` (harness `LIVE`).
fn live_nodes(w: &World) -> usize {
    let mut live = 0;
    for m in &w.models {
        let mut n = m.link;
        let mut steps = 0;
        while n != -1 && steps < w.nodes.len() {
            live += 1;
            steps += 1;
            n = w.nodes[n as usize].i_render_bound;
        }
    }
    live
}

// ---------------------------------------------------------------------------
// Fixture parsing
// ---------------------------------------------------------------------------

fn tok<T: FromStr>(s: &str) -> T
where
    T::Err: Debug,
{
    s.parse()
        .unwrap_or_else(|e| panic!("bad token {s:?}: {e:?}"))
}

fn hf(s: &str) -> f32 {
    let bits = u32::from_str_radix(s, 16).unwrap_or_else(|e| panic!("bad hex {s:?}: {e}"));
    f32::from_bits(bits)
}

fn hvec(t: &[&str]) -> FVector {
    FVector {
        x: hf(t[0]),
        y: hf(t[1]),
        z: hf(t[2]),
    }
}

fn rot(t: &[&str]) -> FRotator {
    FRotator {
        pitch: tok(t[0]),
        yaw: tok(t[1]),
        roll: tok(t[2]),
    }
}

/// Parses an `INIT` state block into the host.
fn parse_world(block: &[&str]) -> World {
    let mut w = World::default();
    for line in block {
        let t: Vec<&str> = line.split_whitespace().collect();
        match t[0] {
            "SURF" => {
                assert_eq!(tok::<usize>(t[1]), w.surfs.len(), "SURF order");
                // SAFETY: FBspSurf is plain data (ints, floats, raw pointers, TArrayRaw); all-zero is valid.
                let mut s: FBspSurf = unsafe { std::mem::zeroed() };
                s.texture = texture_ptr(tok::<u8>(t[2]) == 1);
                s.poly_flags = tok(t[3]);
                s.p_base = tok(t[4]);
                s.v_normal = tok(t[5]);
                s.v_texture_u = tok(t[6]);
                s.v_texture_v = tok(t[7]);
                s.i_light_map = tok(t[8]);
                s.i_brush_poly = tok(t[9]);
                s.pan_u = tok(t[10]);
                s.pan_v = tok(t[11]);
                s.actor = actor_ptr(tok(t[12]));
                s.decals.array_num = tok(t[13]);
                s.nodes.array_num = tok(t[14]);
                w.surfs.push(s);
            }
            "VEC" => {
                assert_eq!(tok::<usize>(t[1]), w.vectors.len(), "VEC order");
                w.vectors.push(hvec(&t[2..5]));
            }
            "PT" => {
                assert_eq!(tok::<usize>(t[1]), w.points.len(), "PT order");
                w.points.push(hvec(&t[2..5]));
            }
            "NODE" => {
                assert_eq!(tok::<usize>(t[1]), w.nodes.len(), "NODE order");
                w.nodes.push(FBspNode {
                    plane: FPlane {
                        x: hf(t[2]),
                        y: hf(t[3]),
                        z: hf(t[4]),
                        w: hf(t[5]),
                    },
                    zone_mask: tok(t[6]),
                    i_vert_pool: tok(t[7]),
                    i_surf: tok(t[8]),
                    i_back: tok(t[9]),
                    i_front: tok(t[10]),
                    i_plane: tok(t[11]),
                    i_collision_bound: tok(t[12]),
                    i_render_bound: tok(t[13]),
                    i_zone: [tok(t[14]), tok(t[15])],
                    num_vertices: tok(t[16]),
                    node_flags: tok(t[17]),
                    i_leaf: [tok(t[18]), tok(t[19])],
                });
            }
            "VERT" => {
                assert_eq!(tok::<usize>(t[1]), w.verts.len(), "VERT order");
                w.verts.push(FVert {
                    p_vertex: tok(t[2]),
                    i_side: tok(t[3]),
                });
            }
            "ACTOR" => {
                assert_eq!(tok::<usize>(t[1]), w.actors.len(), "ACTOR order");
                if t[2] == "plain" {
                    w.actors.push(Actor {
                        mover: false,
                        location: zero_vec(),
                        rotation: zero_rot(),
                        pre_pivot: zero_vec(),
                        saved_pos: zero_vec(),
                        saved_rot: zero_rot(),
                        assimilated: false,
                        special_lit: false,
                        brush: None,
                    });
                } else {
                    assert_eq!(t[2], "mover", "ACTOR kind");
                    w.actors.push(Actor {
                        mover: true,
                        location: hvec(&t[3..6]),
                        rotation: rot(&t[6..9]),
                        pre_pivot: hvec(&t[9..12]),
                        saved_pos: hvec(&t[12..15]),
                        saved_rot: rot(&t[15..18]),
                        assimilated: tok::<u8>(t[18]) == 1,
                        special_lit: tok::<u8>(t[19]) == 1,
                        brush: None,
                    });
                }
            }
            "BRUSH" => {
                let i: usize = tok(t[1]);
                // Negative values are the oracle's -1 (null), -2 (other), -3 (level model).
                w.actors[i].brush = usize::try_from(tok::<i32>(t[2])).ok();
            }
            "MODEL" => {
                assert_eq!(tok::<usize>(t[1]), w.models.len(), "MODEL order");
                w.models.push(Model {
                    link: tok(t[3]),
                    polys: Vec::new(),
                });
            }
            "BPOLY" => {
                let i: usize = tok(t[1]);
                assert_eq!(i + 1, w.models.len(), "BPOLY model");
                assert_eq!(tok::<usize>(t[2]), w.models[i].polys.len(), "BPOLY order");
                // SAFETY: FPoly is plain data (floats, ints, raw pointers); all-zero is valid.
                let mut p: FPoly = unsafe { std::mem::zeroed() };
                p.base = hvec(&t[3..6]);
                p.normal = hvec(&t[6..9]);
                p.texture_u = hvec(&t[9..12]);
                p.texture_v = hvec(&t[12..15]);
                for k in 0..MAX_VERTICES {
                    p.vertex[k] = hvec(&t[15 + 3 * k..18 + 3 * k]);
                }
                p.poly_flags = tok(t[63]);
                p.actor = actor_ptr(tok(t[64]));
                p.num_vertices = tok(t[65]);
                p.i_link = tok(t[66]);
                p.i_brush_poly = tok(t[67]);
                p.pan_u = tok(t[68]);
                p.pan_v = tok(t[69]);
                p.save_poly_index = tok(t[70]);
                p.b_face_drag_sel = tok(t[71]);
                w.models[i].polys.push(p);
            }
            "COORDS" => {}
            "LIVE" => {}
            other => panic!("unexpected INIT line tag {other}"),
        }
    }
    w
}

/// Per-actor `BuildCoords` results recorded by the oracle in a state block.
fn parse_coords(block: &[&str], n_actors: usize) -> Vec<Option<(FCoords, FCoords, f32)>> {
    let mut out = vec![None; n_actors];
    for line in block.iter().filter(|l| l.starts_with("COORDS ")) {
        let t: Vec<&str> = line.split_whitespace().collect();
        let i: usize = tok(t[1]);
        // Tokens 2..26: point (4 vectors), then vector (4 vectors); token 26: orientation.
        let fv = |k: usize| FVector {
            x: hf(t[2 + 3 * k]),
            y: hf(t[3 + 3 * k]),
            z: hf(t[4 + 3 * k]),
        };
        let point = FCoords {
            origin: fv(0),
            x_axis: fv(1),
            y_axis: fv(2),
            z_axis: fv(3),
        };
        let vector = FCoords {
            origin: fv(4),
            x_axis: fv(5),
            y_axis: fv(6),
            z_axis: fv(7),
        };
        out[i] = Some((point, vector, hf(t[26])));
    }
    out
}

fn apply_pose(w: &mut World, rest: &str) {
    let t: Vec<&str> = rest.split_whitespace().collect();
    let i = w.mover_index(tok(t[0]));
    w.actors[i].location = hvec(&t[1..4]);
    w.actors[i].rotation = rot(&t[4..7]);
}

fn check(case: &str, op: &str, got: &[String], want: &[&str]) {
    assert_eq!(got.len(), want.len(), "{case} {op}: line count");
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert_eq!(g.as_str(), *w, "{case} {op}: line {}", i + 1);
    }
}

#[test]
fn dynbsp_tracker_matches_oracle() {
    let lines: Vec<&str> = FIXTURE.lines().collect();
    let mut at = 0;
    let mut cases = 0;
    while at < lines.len() {
        let name = lines[at]
            .strip_prefix("CASE ")
            .unwrap_or_else(|| panic!("expected CASE at line {}", at + 1));
        at += 1;
        cases += 1;

        let mut idle: Option<World> = None;
        let mut tracker: Option<DynBsp<World>> = None;
        loop {
            let line = lines[at];
            at += 1;
            if line == "END" {
                break;
            }
            if let Some(rest) = line.strip_prefix("OP POSE ") {
                let host = match tracker.as_mut() {
                    Some(t) => t.host_mut(),
                    None => idle.as_mut().expect("POSE before INIT"),
                };
                apply_pose(host, rest);
                continue;
            }
            let op_line = line
                .strip_prefix("OP ")
                .unwrap_or_else(|| panic!("unexpected line {line:?}"));
            let mut block: Vec<&str> = Vec::new();
            while lines[at] != "END_STATE" {
                block.push(lines[at]);
                at += 1;
            }
            at += 1;
            let want: Vec<&str> = block
                .iter()
                .copied()
                .filter(|l| !l.starts_with("COORDS "))
                .collect();
            let (op, arg) = op_line.split_once(' ').unwrap_or((op_line, ""));

            match op {
                "INIT" => {
                    let w = parse_world(&block);
                    check(name, op_line, &render(&w, None), &want);
                    idle = Some(w);
                }
                "CTOR" => {
                    let mut w = idle.take().expect("CTOR before INIT");
                    w.coords = parse_coords(&block, w.actors.len());
                    let t = DynBsp::new(w);
                    let sdyn = |i: i32| t.surf_is_dynamic(i);
                    check(
                        name,
                        op_line,
                        &render(t.host(), Some(&sdyn as &dyn Fn(i32) -> bool)),
                        &want,
                    );
                    tracker = Some(t);
                }
                "UPDATE" | "FLUSH" => {
                    let t = tracker.as_mut().expect("operation before CTOR");
                    let n_actors = t.host().actors.len();
                    t.host_mut().coords = parse_coords(&block, n_actors);
                    let k: i32 = tok(arg);
                    let actor = if k < 0 {
                        ptr::null_mut()
                    } else {
                        t.host().mover_obj(k as usize)
                    };
                    if op == "UPDATE" {
                        t.update(actor);
                    } else {
                        t.flush(actor);
                    }
                    let sdyn = |i: i32| t.surf_is_dynamic(i);
                    check(
                        name,
                        op_line,
                        &render(t.host(), Some(&sdyn as &dyn Fn(i32) -> bool)),
                        &want,
                    );
                }
                "DTOR" => {
                    let t = tracker.take().expect("DTOR before CTOR");
                    let w = t.shutdown();
                    check(name, op_line, &render(&w, None), &want);
                }
                other => panic!("unknown oracle op {other}"),
            }
        }
    }
    assert_eq!(cases, 8, "fixture case count");
}
